#ifdef SHADERLOD_DENSITY_DETAIL_COST_CONTROL
#if defined PROGRAM_DEFERRED1
    float worley_1;
    // Intentionally changes density and early-exit occupancy: cost control only.
    if (shaderlodBridgeVersion == 2 && shaderlodEnabled == 1) {
        worley_1 = 0.5; // Declared diagnostic, not a texture mean or opacity match.
